CREATE FUNCTION cleanup_orphaned_layout() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  check_layout_id uuid;
BEGIN
  IF TG_TABLE_NAME = 'user_tracked_layouts' THEN
    check_layout_id := OLD.layout_id;
  ELSE
    check_layout_id := NEW.id;
  END IF;

  DELETE FROM user_panel_layouts
  WHERE id = check_layout_id
    AND user_id IS NULL
    AND NOT EXISTS (
      SELECT 1
      FROM user_tracked_layouts
      WHERE layout_id = check_layout_id
    );

  RETURN COALESCE(NEW, OLD);
END;
$$;

CREATE FUNCTION insert_default_data_grant() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO data_grants (user_id, source, storage_bytes, description)
  VALUES (NEW.id, 'base', 150000000, 'Default storage allocation');
  RETURN NEW;
END;
$$;

CREATE FUNCTION river_job_state_in_bitmask(bitmask bit, state river_job_state) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT CASE state
        WHEN 'available' THEN get_bit(bitmask, 7)
        WHEN 'cancelled' THEN get_bit(bitmask, 6)
        WHEN 'completed' THEN get_bit(bitmask, 5)
        WHEN 'discarded' THEN get_bit(bitmask, 4)
        WHEN 'pending'   THEN get_bit(bitmask, 3)
        WHEN 'retryable' THEN get_bit(bitmask, 2)
        WHEN 'running'   THEN get_bit(bitmask, 1)
        WHEN 'scheduled' THEN get_bit(bitmask, 0)
        ELSE 0
    END = 1;
$$;

CREATE TABLE data_grants (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    source text NOT NULL,
    storage_bytes bigint NOT NULL,
    description text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone
);

CREATE TABLE log_file (
    id uuid NOT NULL,
    owner uuid NOT NULL,
    wow_log_id uuid NOT NULL,
    hash text NOT NULL,
    size_bytes bigint NOT NULL,
    mime_type text NOT NULL,
    created_at timestamp with time zone,
    updated_at timestamp with time zone,
    storage_deleted_at timestamp with time zone,
    compressed_size_bytes bigint,
    content_encoding text
);

COMMENT ON COLUMN log_file.size_bytes IS 'Original uncompressed file size in bytes';

COMMENT ON COLUMN log_file.storage_deleted_at IS 'The timestamp when the file was deleted from storage. This allows us to keep track of files that have been removed from storage, even if the log_file record still exists in the database.';

COMMENT ON COLUMN log_file.compressed_size_bytes IS 'Compressed file size in bytes (NULL if stored uncompressed)';

COMMENT ON COLUMN log_file.content_encoding IS 'Content encoding used for storage (e.g., gzip), NULL if stored raw';

CREATE VIEW user_storage_limits AS
 SELECT data_grants.user_id,
    sum(data_grants.storage_bytes) AS max_storage_bytes,
    max(data_grants.created_at) AS updated_at
   FROM data_grants
  WHERE ((data_grants.expires_at IS NULL) OR (data_grants.expires_at > now()))
  GROUP BY data_grants.user_id;

CREATE TABLE users (
    id uuid NOT NULL,
    username text NOT NULL,
    email text NOT NULL,
    created_at timestamp with time zone,
    updated_at timestamp with time zone,
    default_desktop_layout_id uuid,
    default_mobile_layout_id uuid
);

CREATE VIEW chronicle_users AS
 SELECT u.id,
    u.username,
    u.email,
    u.created_at,
    u.updated_at,
    COALESCE(sl.max_storage_bytes, (0)::numeric) AS max_storage_bytes,
    sl.updated_at AS data_limit_updated_at,
    COALESCE(lf.total_size_bytes, (0)::numeric) AS consumed_storage_bytes
   FROM ((public.users u
     LEFT JOIN user_storage_limits sl ON ((sl.user_id = u.id)))
     LEFT JOIN ( SELECT log_file.owner,
            sum(COALESCE(log_file.compressed_size_bytes, log_file.size_bytes)) AS total_size_bytes
           FROM log_file
          WHERE (log_file.storage_deleted_at IS NULL)
          GROUP BY log_file.owner) lf ON ((lf.owner = u.id)));

